    c: "import 'package:flutter/material.dart';\n\nclass Prefs extends StatefulWidget {\n  const Prefs({super.key});\n  @override\n  State<Prefs> createState() => _PrefsState();\n}\n\nclass _PrefsState extends State<Prefs> {\n  String size = 'M';\n  double volume = 0.5;\n  @override\n  Widget build(BuildContext context) => Column(children: [\n        DropdownButton<String>(\n          value: size,\n          items: const [\n            DropdownMenuItem(value: 'S', child: Text('Small')),\n            DropdownMenuItem(value: 'M', child: Text('Medium')),\n          ],\n          onChanged: (v) => setState(() => size = v!),\n        ),\n        Slider(value: volume, onChanged: (v) => setState(() => volume = v)),\n        Text('Size $size, volume ${volume.toStringAsFixed(1)}'),\n      ]);\n}\n\nvoid main() {\n  runApp(const MaterialApp(home: Scaffold(body: Prefs())));\n}",
    m: ["Switch(value: true, onChanged: (v) {}) // never changes", "Switch(value: enabled, onChanged: (v) => setState(() => enabled = v))", 'Selection widgets are controlled; if you never store the new value, the control snaps back.'],
