    c: "class Counter extends ChangeNotifier {\n  int _value = 0;\n  int get value => _value;\n  void increment() {\n    _value++;\n    notifyListeners();\n  }\n}\n\nvoid main() {\n  final c = Counter();\n  c.addListener(() => print('changed to ${c.value}'));\n  c.increment();\n  c.increment();\n}",
    m: ["void add(Item i) {\n  _items.add(i); // listeners never told\n}", "void add(Item i) {\n  _items.add(i);\n  notifyListeners();\n}", 'Without notifyListeners() no widget rebuilds after the change.'],
